// Turns Moodle's nested reply into one item per open assignment.
const res = $input.first().json;
if (res.exception || res.errorcode) {
  // e.g. errorcode 'invalidtoken' -> the error workflow emails you
  throw new Error(`Moodle API error: ${res.errorcode || ''} ${res.message || ''}`.trim());
}
const out = [];
for (const course of res.courses || []) {
  // keep only the English part of the course name
  const m = course.fullname.match(/\{mlang en\}(.*?)\{mlang\}/);
  const courseName = m ? m[1] : course.fullname;

  for (const a of course.assignments) {
    if (a.duedate * 1000 < Date.now()) continue; // skip assignments already past due

    // attachments + files embedded in the description (images etc.)
    let files = [...(a.introattachments || []), ...(a.introfiles || [])]
      .map(f => ({ name: f.filename, url: f.fileurl, type: f.mimetype }));

    // fallback: <img src="..."> tags inside the description
    for (const [, src] of (a.intro || '').matchAll(/<img[^>]+src="([^"]+)"/g)) {
      if (!files.some(f => f.url === src)) {
        files.push({ name: src.split('/').pop(), url: src, type: 'image' });
      }
    }

    // plain-text version of the description
    const text = (a.intro || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

    out.push({ json: {
      course: courseName,
      courseId: course.id,
      assignmentId: a.id,
      name: a.name,
      due: new Date(a.duedate * 1000).toLocaleString('en-GB', { timeZone: 'Asia/Amman' }),
      instructions: text,
      files,
    }});
  }
}
return out;

// Keep only assignments that haven't been emailed yet.
// "sent" is remembered in the workflow's static data, which n8n only SAVES
// during automatic (published) runs. Manual runs read it but don't change it.
const s = $('Settings').first().json;
const store = $getWorkflowStaticData('global');
const sent = store.sent || {};
const seeded = String(s.alreadySentIds || '').split(',').map(x => x.trim()).filter(Boolean);
const testId = String(s.testOnlyAssignmentId || '').trim();

return $input.all().filter(item => {
  const id = String(item.json.assignmentId);
  if (testId) return id === testId;          // test mode: only this one, even if already sent
  return !sent[id] && !seeded.includes(id);
});

// No attachment or image: turn the typed instructions into a small text file,
// so the rest of the workflow can treat it like any other assignment file.
const a = $('Current assignment').first().json;
const text = `Course: ${a.course}\nAssignment: ${a.name}\nDue: ${a.due}\n\n${a.instructions || '(The assignment has no description.)'}`;
return [{
  json: {},
  binary: {
    data: {
      data: Buffer.from(text, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'assignment.txt',
    },
  },
}];

const files = [];
const seen = new Set();
for (const item of $input.all()) {             // one item per course section
  const section = item.json;
  for (const mod of section.modules || []) {
    for (const f of mod.contents || []) {
      if (f.type !== 'file' || f.mimetype !== 'application/pdf') continue;
      if (seen.has(f.filename)) continue;      // skip duplicates
      seen.add(f.filename);
      files.push({
        n: files.length + 1,
        section: section.name.replace(/&amp;/g, '&'),
        title: mod.name.replace(/&amp;/g, '&'),
        fileName: f.filename,
        url: f.fileurl,
      });
    }
  }
}
const menu = files.map(f => `${f.n}. [${f.section}] ${f.title} (${f.fileName})`).join('\n');

// carry the assignment file along so the next Gemini call can read it
return [{ json: { files, menu }, binary: { data: $('Assignment file').first().binary.data } }];

parameters.text:
=The attached file is a university assignment (a PDF, an image of the questions, or plain text).
Assignment: {{ $('Current assignment').first().json.name }} ({{ $('Current assignment').first().json.course }})
Description text (may be empty): {{ $('Current assignment').first().json.instructions }}

Below is a numbered list of this course's lecture files. Pick up to {{ $('Settings').first().json.maxLectureFiles }} files that are most useful for understanding and solving this assignment. Prefer the main slides for each relevant topic; add notes or examples only if clearly helpful.
Reply with ONLY a JSON array of the numbers, for example [3, 7, 12]. If nothing is relevant, reply [].

{{ $json.menu }}

parameters.jsCode:
// Gemini's reply, e.g. "[1, 7, 23]" or "```json [1, 7, 23] ```"
const raw = $input.first().json.content.parts[0].text;
const match = raw.match(/\[[\d,\s]*\]/);
let picks = [];
try { picks = match ? JSON.parse(match[0]) : []; } catch (e) { picks = []; }

const files = $('List course files').first().json.files;
let chosen = [...new Set(picks)]
  .map(n => files.find(f => f.n === n))
  .filter(Boolean)          // ignore numbers that don't exist
  .slice(0, Number($('Settings').first().json.maxLectureFiles) || 4);

// fallback: if Gemini picked nothing usable, take the first file
// so the rest of the workflow still runs
if (chosen.length === 0) chosen = files.slice(0, 1);

return chosen.map(f => ({ json: f }));

// start with the assignment file (PDF, image or text)
const binary = { assignment: $('Assignment file').first().binary.data };
const names = ['assignment'];
const lines = ['1. assignment: the assignment itself'];

// add each downloaded lecture file
const picked = $('Split chosen').all();
$input.all().forEach((item, i) => {
  const key = `slide${i + 1}`;
  binary[key] = item.binary.data;
  names.push(key);
  const f = picked[i].json;
  lines.push(`${i + 2}. ${key}: ${f.fileName} | "${f.title}" (section: ${f.section})`);
});

return [{
  json: {
    binaryNames: names.join(','),   // e.g. "assignment,slide1,slide2"
    fileList: lines.join('\n'),
  },
  binary,
}];

// Gemini's HTML answer (strip ``` fences in case it added them)
const parts = $input.first().json.content?.parts || [];
const html = parts.filter(p => p.text && !p.thought).map(p => p.text).join('')
  .replace(/^```html\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

// Build a clean file name like "20261-Algorithms-AllSec-3-F - Phase 1"
const a = $('Current assignment').first().json;
const fileName = `${a.course} - ${a.name}`.replace(/[\\/:*?"<>|]/g, '');

// Wrap it as a full HTML page (utf-8 keeps Arabic text safe)
const page = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${fileName}</title></head><body>${html}</body></html>`;

return [{
  json: { fileName },
  binary: {
    data: {
      data: Buffer.from(page, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: fileName + '.html',
    },
  },
}];

