// Only reached after the email was sent, so a failed run gets retried next time.
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const a = $('Current assignment').first().json;
store.sent[String(a.assignmentId)] = new Date().toISOString();
return [{ json: { markedAsSent: a.assignmentId, name: a.name } }];
